CREATE TABLE IF NOT EXISTS "bf_v10"."menu_experiment_exposures" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "visitor_key" text NOT NULL,
  "experiment_key" text NOT NULL,
  "experiment_variant" text NOT NULL,
  "menu_item_id" text NOT NULL REFERENCES "bf_v10"."menu_items"("id") ON DELETE cascade,
  "exposed_at" timestamp with time zone NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS "menu_experiment_exposures_unique_idx"
  ON "bf_v10"."menu_experiment_exposures"
  ("visitor_key", "experiment_key", "experiment_variant", "menu_item_id");

CREATE INDEX IF NOT EXISTS "menu_experiment_exposures_experiment_idx"
  ON "bf_v10"."menu_experiment_exposures" ("experiment_key");
